let request = await claimRequest('resume-probe');
while (request && request.id !== created.id) request = await claimRequest('resume-probe');
if (!request) {
  console.log(JSON.stringify({ status: 'skipped', reason: 'service worker claimed the request first' }));
  await pool.end();
