const partial = ERASURE_STEPS.slice(0, 3);
await runErasureRequest({ ...request, id: request.id });
const finished = await completedSteps(request.id);
assert.equal(finished.size, ERASURE_STEPS.length, 'first pass did not finish every step');
assert.ok(partial.every((step) => finished.has(step)));

