await markRequestFailed({ ...request, status: 'processing' }, 'purge_projections_failed');
const resumed = await pool.query<{ status: string; last_error: string }>(
  `SELECT status,last_error FROM privacy.erasure_requests WHERE id=$1`, [request.id],
);
assert.equal(resumed.rows[0]!.status, 'failed');
await runErasureRequest(request);
await markRequestCompleted(request);

