  `SELECT (SELECT status FROM privacy.erasure_requests WHERE id=$1) status,
          (SELECT count(*)::text FROM privacy.erasure_steps WHERE request_id=$1) steps,
          (SELECT count(*)::text FROM customers.customers WHERE id=$2) customers,
          (SELECT count(*)::text FROM customers.addresses WHERE customer_id=$2) addresses,
          (SELECT count(*)::text FROM privacy.erased_customers WHERE customer_id=$2) tombstones`,
  [request.id, customer.id],
);
const row = state.rows[0]!;
assert.equal(row.status, 'completed');
assert.equal(row.steps, String(ERASURE_STEPS.length), 'steps were recorded more than once');
assert.equal(row.customers, '0', 'the customer record survived');
assert.equal(row.addresses, '0', 'addresses survived');
assert.equal(row.tombstones, '1');

console.log(JSON.stringify({ status: 'verified', requestId: request.id, ...row }, null, 2));
await pool.end();
